-- T35 — NEX-065 (índice fiscal): reproduce el índice REAL de NEX-047 en un esquema descartable y comprueba que (a) la comparación textual antigua (LIKE con comillas mal escapadas) da un FALSO NEGATIVO y
-- (b) la verificación por catálogos de NEX-065/preflight/verificar reconoce la definición real y rechaza variantes incorrectas. NO crea ni modifica nada en public. Base descartable; NO ejecutada por la IA.
\i _helpers.sql

DO $t$
DECLARE
  v_def text;
BEGIN
  CREATE SCHEMA t35;
  CREATE TABLE t35.documentos_electronicos (empresa_id uuid, tipo text, establecimiento text, punto_expedicion text, numero text, serie text, extra text);
  CREATE UNIQUE INDEX documentos_electronicos_numero_key ON t35.documentos_electronicos (empresa_id, tipo, establecimiento, punto_expedicion, numero, coalesce(serie, ''));
  SELECT indexdef INTO v_def FROM pg_indexes WHERE schemaname = 't35' AND indexname = 'documentos_electronicos_numero_key';
  PERFORM pg_temp.ok(v_def LIKE '%COALESCE(serie, ''''::text)%', 'la definición real de PostgreSQL contiene COALESCE(serie, ''''::text) (dos comillas): ' || v_def);
  PERFORM pg_temp.ok(NOT (v_def LIKE 'CREATE UNIQUE INDEX%' AND v_def LIKE '%empresa_id, tipo, establecimiento, punto_expedicion, numero, COALESCE(serie, ''::text)%'), 'la comparación textual ANTIGUA da falso negativo sobre el índice real (reproduce la falla de aplicación)');
  PERFORM pg_temp.ok(EXISTS (SELECT 1 FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid JOIN pg_class t ON t.oid = i.indrelid JOIN pg_namespace n ON n.oid = t.relnamespace WHERE n.nspname = 't35' AND t.relname = 'documentos_electronicos' AND c.relname = 'documentos_electronicos_numero_key' AND i.indisunique AND i.indisvalid AND i.indisready AND i.indpred IS NULL AND i.indnkeyatts = 6 AND i.indnatts = 6 AND i.indkey[5] = 0 AND ARRAY(SELECT pg_get_indexdef(i.indexrelid, k, true) FROM generate_series(1, 5) k) = ARRAY['empresa_id', 'tipo', 'establecimiento', 'punto_expedicion', 'numero'] AND lower(replace(pg_get_indexdef(i.indexrelid, 6, true), ' ', '')) = 'coalesce(serie,' || repeat(chr(39), 2) || '::text)'), 'la verificación por catálogos reconoce el índice real');
  DROP INDEX t35.documentos_electronicos_numero_key;
  CREATE INDEX documentos_electronicos_numero_key ON t35.documentos_electronicos (empresa_id, tipo, establecimiento, punto_expedicion, numero, coalesce(serie, ''));
  PERFORM pg_temp.ok(NOT EXISTS (SELECT 1 FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid JOIN pg_class t ON t.oid = i.indrelid JOIN pg_namespace n ON n.oid = t.relnamespace WHERE n.nspname = 't35' AND t.relname = 'documentos_electronicos' AND c.relname = 'documentos_electronicos_numero_key' AND i.indisunique AND i.indisvalid AND i.indisready AND i.indpred IS NULL AND i.indnkeyatts = 6 AND i.indnatts = 6 AND i.indkey[5] = 0 AND ARRAY(SELECT pg_get_indexdef(i.indexrelid, k, true) FROM generate_series(1, 5) k) = ARRAY['empresa_id', 'tipo', 'establecimiento', 'punto_expedicion', 'numero'] AND lower(replace(pg_get_indexdef(i.indexrelid, 6, true), ' ', '')) = 'coalesce(serie,' || repeat(chr(39), 2) || '::text)'), 'rechaza el índice NO único');
  DROP INDEX t35.documentos_electronicos_numero_key;
  CREATE UNIQUE INDEX documentos_electronicos_numero_key ON t35.documentos_electronicos (empresa_id, tipo, establecimiento, punto_expedicion, numero, serie);
  PERFORM pg_temp.ok(NOT EXISTS (SELECT 1 FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid JOIN pg_class t ON t.oid = i.indrelid JOIN pg_namespace n ON n.oid = t.relnamespace WHERE n.nspname = 't35' AND t.relname = 'documentos_electronicos' AND c.relname = 'documentos_electronicos_numero_key' AND i.indisunique AND i.indisvalid AND i.indisready AND i.indpred IS NULL AND i.indnkeyatts = 6 AND i.indnatts = 6 AND i.indkey[5] = 0 AND ARRAY(SELECT pg_get_indexdef(i.indexrelid, k, true) FROM generate_series(1, 5) k) = ARRAY['empresa_id', 'tipo', 'establecimiento', 'punto_expedicion', 'numero'] AND lower(replace(pg_get_indexdef(i.indexrelid, 6, true), ' ', '')) = 'coalesce(serie,' || repeat(chr(39), 2) || '::text)'), 'rechaza el índice único ordinario (la serie NULL no cuenta como valor)');
  DROP INDEX t35.documentos_electronicos_numero_key;
  CREATE UNIQUE INDEX documentos_electronicos_numero_key ON t35.documentos_electronicos (empresa_id, tipo, establecimiento, punto_expedicion, numero, coalesce(serie, '')) WHERE extra IS NULL;
  PERFORM pg_temp.ok(NOT EXISTS (SELECT 1 FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid JOIN pg_class t ON t.oid = i.indrelid JOIN pg_namespace n ON n.oid = t.relnamespace WHERE n.nspname = 't35' AND t.relname = 'documentos_electronicos' AND c.relname = 'documentos_electronicos_numero_key' AND i.indisunique AND i.indisvalid AND i.indisready AND i.indpred IS NULL AND i.indnkeyatts = 6 AND i.indnatts = 6 AND i.indkey[5] = 0 AND ARRAY(SELECT pg_get_indexdef(i.indexrelid, k, true) FROM generate_series(1, 5) k) = ARRAY['empresa_id', 'tipo', 'establecimiento', 'punto_expedicion', 'numero'] AND lower(replace(pg_get_indexdef(i.indexrelid, 6, true), ' ', '')) = 'coalesce(serie,' || repeat(chr(39), 2) || '::text)'), 'rechaza el índice parcial (con filtro)');
  DROP INDEX t35.documentos_electronicos_numero_key;
  CREATE UNIQUE INDEX documentos_electronicos_numero_key ON t35.documentos_electronicos (empresa_id, tipo, establecimiento, punto_expedicion, numero, coalesce(serie, 'x'));
  PERFORM pg_temp.ok(NOT EXISTS (SELECT 1 FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid JOIN pg_class t ON t.oid = i.indrelid JOIN pg_namespace n ON n.oid = t.relnamespace WHERE n.nspname = 't35' AND t.relname = 'documentos_electronicos' AND c.relname = 'documentos_electronicos_numero_key' AND i.indisunique AND i.indisvalid AND i.indisready AND i.indpred IS NULL AND i.indnkeyatts = 6 AND i.indnatts = 6 AND i.indkey[5] = 0 AND ARRAY(SELECT pg_get_indexdef(i.indexrelid, k, true) FROM generate_series(1, 5) k) = ARRAY['empresa_id', 'tipo', 'establecimiento', 'punto_expedicion', 'numero'] AND lower(replace(pg_get_indexdef(i.indexrelid, 6, true), ' ', '')) = 'coalesce(serie,' || repeat(chr(39), 2) || '::text)'), 'rechaza una expresión distinta (COALESCE con otro valor)');
  DROP INDEX t35.documentos_electronicos_numero_key;
  CREATE UNIQUE INDEX documentos_electronicos_numero_key ON t35.documentos_electronicos (empresa_id, tipo, establecimiento, numero, punto_expedicion, coalesce(serie, ''));
  PERFORM pg_temp.ok(NOT EXISTS (SELECT 1 FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid JOIN pg_class t ON t.oid = i.indrelid JOIN pg_namespace n ON n.oid = t.relnamespace WHERE n.nspname = 't35' AND t.relname = 'documentos_electronicos' AND c.relname = 'documentos_electronicos_numero_key' AND i.indisunique AND i.indisvalid AND i.indisready AND i.indpred IS NULL AND i.indnkeyatts = 6 AND i.indnatts = 6 AND i.indkey[5] = 0 AND ARRAY(SELECT pg_get_indexdef(i.indexrelid, k, true) FROM generate_series(1, 5) k) = ARRAY['empresa_id', 'tipo', 'establecimiento', 'punto_expedicion', 'numero'] AND lower(replace(pg_get_indexdef(i.indexrelid, 6, true), ' ', '')) = 'coalesce(serie,' || repeat(chr(39), 2) || '::text)'), 'rechaza columnas en otro orden');
  DROP INDEX t35.documentos_electronicos_numero_key;
  PERFORM pg_temp.ok(NOT EXISTS (SELECT 1 FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid JOIN pg_class t ON t.oid = i.indrelid JOIN pg_namespace n ON n.oid = t.relnamespace WHERE n.nspname = 't35' AND t.relname = 'documentos_electronicos' AND c.relname = 'documentos_electronicos_numero_key' AND i.indisunique AND i.indisvalid AND i.indisready AND i.indpred IS NULL AND i.indnkeyatts = 6 AND i.indnatts = 6 AND i.indkey[5] = 0 AND ARRAY(SELECT pg_get_indexdef(i.indexrelid, k, true) FROM generate_series(1, 5) k) = ARRAY['empresa_id', 'tipo', 'establecimiento', 'punto_expedicion', 'numero'] AND lower(replace(pg_get_indexdef(i.indexrelid, 6, true), ' ', '')) = 'coalesce(serie,' || repeat(chr(39), 2) || '::text)'), 'rechaza la ausencia del índice');
  DROP SCHEMA t35 CASCADE;
  RAISE NOTICE 'T35 completada';
END $t$;
